"""Three-station/infrastructure-junction project previews; not a grid generator."""
from .project_workflow_tools import GenerateLineProjectPreview,ProjectWorkflowTools
from .tools import sha
from ..errors import APIError

class BranchNetworkTools(ProjectWorkflowTools):
    def preview(self,args):
        self.readonly(args)
        from .signal_protection.branch_network import generate_network
        state=self.load_project(args.source_project);self.project(state)
        if args.header_document not in state['documents']:raise APIError('HEADER_DOCUMENT','Selected header document absent')
        path=self.path(args.shape_archive.path);shapes=self.secure_bytes(path)
        if sha(shapes)!=args.shape_archive.sha256:raise APIError('SOURCE_CHANGED','Shape source differs from binding')
        templates={k:state['files'][state['roles'][k]]for k in ('depot','trains','courses','timetable')}
        try:members,receipt=generate_network(state['documents'][args.header_document],shapes,templates,args.spec)
        except (ValueError,TypeError,KeyError,IndexError,OverflowError)as exc:
            raise APIError('BRANCH_INVALID','Outside the finite three-arm junction project domain',str(exc)[:500])from exc
        manifest=self.output_manifest(members)
        expected={'header':sha(state['documents'][args.header_document]),'shapes':sha(shapes),**{k:sha(b)for k,b in templates.items()}}
        if type(receipt)is not dict or receipt.get('source_sha256')!=expected or receipt.get('members')!=manifest:raise APIError('PREVIEW_MANIFEST','Branch receipt does not match actual source/output bytes')
        self.recheck(state)
        if self.secure_bytes(path)!=shapes:raise APIError('SOURCE_CHANGED','Shape source changed during preview')
        return {'tool':'opentrack_preview_three_station_branch_project','preview_only':True,'saved':False,'native_runtime_ready':False,'publication_review_pending':True,'source_bindings':args.source_project.model_dump(),'shape_binding':args.shape_archive.model_dump(),'output_files':manifest,'receipt':receipt,'limitations':['Three station documents plus one infrastructure-only junction document, not a three-by-three grid or arbitrary junction.','Point stations and empty traffic catalogs; no stopping-region or operating-service claim.','Geometry is a schematic, not engineered physical alignment or runtime protection certification.','No generated bytes are saved or published.']}

def tool_definitions(root):
    service=BranchNetworkTools(root)
    return [('opentrack_preview_three_station_branch_project','Read-only native archive preview for a bounded three-arm triangle junction: three station documents, one infrastructure-only junction, reciprocal connectors and six directed itineraries. Rejects grids and arbitrary crossings; empty traffic, no save or native execution.',GenerateLineProjectPreview,service.preview)]
